package com.friendslikethese.backend.registration;import com.friendslikethese.backend.event.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import java.time.OffsetDateTime;
@RestController @RequestMapping("/api/public") public class PublicRegistrationController{private final EventService events;private final String formUrl;public PublicRegistrationController(EventService events,@Value("${app.registration.form-url:}")String formUrl){this.events=events;this.formUrl=formUrl;}@GetMapping("/registration") public PublicRegistrationResponse registration(){EventResponse e=events.getCurrentEvent();boolean open=e.status()==EventStatus.REGISTRATION_OPEN&&(e.registrationDeadline()==null||!OffsetDateTime.now().isAfter(e.registrationDeadline()));return new PublicRegistrationResponse(open,e.registrationDeadline(),formUrl);}}
